                best_delta = delta
                best_pos = p
            p += 1
        return best_pos, best_delta

    def two_opt(rt):
        if len(rt) < 3:
            return rt[:]
        rt = rt[:]
        improved = True
        while improved:
            improved = False
            n = len(rt)
            i = 0
            while i < n - 1:
                a = depot if i == 0 else rt[i - 1]
                b = rt[i]
                j = i + 1
                while j < n:
                    c = rt[j]
                    dnode = depot if j == n - 1 else rt[j + 1]
                    old = dist(a, b) + dist(c, dnode)
                    new = dist(a, c) + dist(b, dnode)
                    if new + 1e-12 < old:
                        rt = rt[:i] + rt[i:j + 1][::-1] + rt[j + 1:]
                        improved = True
                        n = len(rt)
                        break
                    j += 1
                if improved:
                    break
                i += 1
        return rt

    def improve_routes(routes):
        routes = [r[:] for r in routes if r]
        changed = True
        while changed:
            changed = False

            i = 0
            while i < len(routes):
                routes[i] = two_opt(routes[i])
                i += 1

            best_move = None
            best_gain = 0.0
            i = 0
            while i < len(routes):
                rt = routes[i]
                j = 0
                while j < len(rt):
                    cid = rt[j]
                    if len(rt) == 1:
                        rem_cost = dist(depot, cid) + dist(cid, depot)
                    elif j == 0:
                        rem_cost = dist(depot, cid) + dist(cid, rt[1]) - dist(depot, rt[1])
                    elif j == len(rt) - 1:
                        rem_cost = dist(rt[-2], cid) + dist(cid, depot) - dist(rt[-2], depot)
                    else:
                        rem_cost = dist(rt[j - 1], cid) + dist(cid, rt[j + 1]) - dist(rt[j - 1], rt[j + 1])

                    k = 0
                    while k < len(routes):
                        if k != i and route_load(routes[k]) + demand.get(cid, 0) <= capacity:
                            pos, ins = best_insertion(routes[k], cid)
                            gain = rem_cost - ins
                            if gain > best_gain + 1e-12:
                                best_gain = gain
                                best_move = (i, j, k, pos)
                        k += 1
                    j += 1
                i += 1

            if best_move is not None:
                i, j, k, pos = best_move
                cid = routes[i][j]
                routes[i].pop(j)
                if not routes[i]:
                    routes.pop(i)
                    if k > i:
                        k -= 1
                routes[k].insert(pos, cid)
                changed = True
                continue

            best_swap = None
            best_gain = 0.0
            i = 0
            while i < len(routes):
                j = i + 1
                while j < len(routes):
                    r1 = routes[i]
                    r2 = routes[j]
                    c1i = 0
                    while c1i < len(r1):
                        c1 = r1[c1i]
                        c2i = 0
                        while c2i < len(r2):
                            c2 = r2[c2i]
                            l1 = route_load(r1) - demand.get(c1, 0) + demand.get(c2, 0)
                            l2 = route_load(r2) - demand.get(c2, 0) + demand.get(c1, 0)
                            if l1 <= capacity and l2 <= capacity:
                                nr1 = r1[:]
                                nr2 = r2[:]
                                nr1[c1i] = c2
                                nr2[c2i] = c1
                                delta = (route_cost(r1) + route_cost(r2)) - (route_cost(nr1) + route_cost(nr2))
                                if delta > best_gain + 1e-12:
                                    best_gain = delta
                                    best_swap = (i, c1i, j, c2i)
                            c2i += 1
                        c1i += 1
                    j += 1
                i += 1

            if best_swap is not None:
                i, a, j, b = best_swap
                routes[i][a], routes[j][b] = routes[j][b], routes[i][a]
                changed = True

        return [r for r in routes if r]

    routes = improve_routes(routes)

    # final deterministic repair for any capacity overflow
    repaired = []
    for rt in routes:
        cur = []
        load = 0
        for cid in rt:
            d = demand.get(cid, 0)
            if cur and load + d > capacity:
                repaired.append(cur)
                cur = [cid]
                load = d
            else:
                cur.append(cid)
                load += d
        if cur:
            repaired.append(cur)

    routes = repaired

    # ensure every customer appears exactly once
    seen = {}
    for rt in routes:
        for cid in rt:
            seen[cid] = seen.get(cid, 0) + 1

    missing = [cid for cid in customers_ids if seen.get(cid, 0) == 0]
    if missing:
        for cid in missing:
            placed = False
            best_idx = None
            best_pos = None
            best_delta = None
            for i, rt in enumerate(routes):
                if route_load(rt) + demand.get(cid, 0) <= capacity:
                    pos, delta = best_insertion(rt, cid)
                    if best_delta is None or delta < best_delta - 1e-12:
                        best_delta = delta
                        best_idx = i
                        best_pos = pos
            if best_idx is not None:
                routes[best_idx].insert(best_pos, cid)
                placed = True
            if not placed:
                routes.append([cid])

    # remove duplicates if any by keeping first occurrence
    assigned = set()
    final_routes = []
    for rt in routes:
        new_rt = []
        for cid in rt:
            if cid not in assigned and cid != depot:
                assigned.add(cid)
                new_rt.append(cid)
        if new_rt:
            final_routes.append(new_rt)

    unassigned = [cid for cid in customers_ids if cid not in assigned]
    for cid in unassigned:
        final_routes.append([cid])

    return final_routes
